SELECT CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, MIN(t.amount) AS min_amount, SORT_ARRAY(COLLECT_SET(t.merchant)) AS merchant_list FROM transactions t LEFT OUTER JOIN accounts a ON t.account_id = a.id JOIN customers c ON a.customer_id = c.id WHERE a.status = 'OPEN' GROUP BY CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END
